        <div class="section-head"><div><span>RECENT POSTS</span><h2>{{category||tag||keyword?'筛选结果':'最近文章'}}</h2></div><small>{{archive.posts.length}} 篇文章</small></div>
        <div v-if="showCategories" class="category-strip"><button :class="{active:!category}" @click="category='';load()">全部</button><button v-for="item in archive.categories" :key="item" :class="{active:category===item}" @click="category=item;load()">{{item}}</button></div>
