import{onMounted,reactive,ref}from'vue';import{listPublicBlog,type BlogArchive}from'@/api/blog';const archive=reactive<BlogArchive>({posts:[],categories:[],tags:[]}),keyword=ref(''),category=ref(''),tag=ref(''),loading=ref(false),showCategories=ref(false),searchInput=ref<HTMLInputElement>();async function load(){loading.value=true;try{Object.assign(archive,(await listPublicBlog({keyword:keyword.value||undefined,category:category.value||undefined,tag:tag.value||undefined,site:'WORK'})).data);}finally{loading.value=false;}}function resetFilters(){keyword.value='';category.value='';tag.value='';load();}function focusSearch(){searchInput.value?.focus();document.querySelector('.search-box')?.scrollIntoView({behavior:'smooth',block:'center'});}const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'2-digit'});const tags=(v:string|null)=>v?v.split(',').map(x=>x.trim()).filter(Boolean):[];const readingTime=(summary:string|null)=>Math.max(1,Math.ceil((summary?.length||300)/180));onMounted(()=>{document.title='工作记录';load();});
</script>
